\u0054\u005a\u0052\u004c\u0076\u006d\u0040\u0063\u0032\u0021\u0070\u002b\u0037\u0029\u0038\u0029\u0021\u0059\u0050\u0029\u0058\u0076\u006b\u0034\u0028\u0051\u0021\u0059\u0079\u003d\u004d\u005d\u0063\u0057\u007d\u0061\u0062\u0054\u0046\u0025\u006a\u0064\u0079\u0059\u002e\u0054\u007b\u0038\u0073\u002c\u0054\u0074\u0040\u006d\u0020\u0022\u0031\u0059\u006d\u004b\u0040\u004c\u0078\u0030\u0042\u0040\u004e\u0033\u0050\u0020\u004b\u0042\u0068\u0056\u0022\u0052\u0022\u003d\u0073\u0076\u0050\u0030\u0070\u0064\u0059\u004d\u006b\u0032\u006c\u003a\u0024\u0039\u0029\u0032\u0033\u004b\u0038\u0021\u003a\u0041\u003d\u0034\u007c\u0058\u007e\u0027\u004c\u0066\u0060\u0049\u0059\u0037\u0029\u006c\u0052\u0047\u0061\u0045\u004d\u002e\u0055\u002b\u0069\u004b\u004d\u0078\u0045\u0047\u0028\u007e\u004f\u0078\u003b\u0063\u0055\u006b\u0068\u0062\u0024\u0067\u0022\u0055\u0025\u004a\u0065\u0063\u0064\u0065\u0025\u005b\u002e\u003d\u0031\u0074\u002e\u007e\u002e\u003a\u006c\u0060\u0064\u0027\u0061\u0025\u006e\u0071\u0071\u005e\u0076\u004c\u0059\u0052\u003e\u004f\u0038\u0079\u0050\u0039\u006f\u006c\u0039\u005a\u0021\u0074\u005b\u0076\u003e\u004f\u0052\u003a\u0056\u0058\u0060\u002c\u0047\u0076\u0023\u0033\u0046\u0071\u005e\u006d\u0051\u0074\u005f\u0063\u0065\u0054\u005e\u0056\u002f\u0042\u0055\u007e\u007b\u0079\u0021\u004a\u0040\u0038\u0029\u0046\u004d\u0072\u0038\u0036\u0050\u003b\u0040\u003f\u0044\u0035\u0033\u0068\u0051\u0061\u0026\u0025\u004d\u0055\u0035\u0020\u0043\u004e\u0074\u0038\u0043\u003f\u005f\u0073\u0044\u003d\u0054\u005c\u0041\u0041\u003e\u007a\u0072\u0023\u0038\u0056\u006a\u003a\u004e\u0065\u0029\u0073\u0028\u0076\u0023\u005d\u0046\u007e\u005f\u0021\u006c\u0033\u003f\u007e\u003d\u005c\u004a\u0033\u005a\u0046\u0061\u0044\u005c\u006a\u0051\u0044\u0059\u0050\u007b\u0076\u0070\u003f\u0058\u0076\u0077\u0050\u005a\u0039\u004b\u0042\u006a\u0062\u0059\u006b\u0061\u0073\u006f\u006e\u0040\u0053\u006f\u0053\u006f\u002f\u002e\u0046\u004f\u0037\u002e\u0050\u004d\u0049\u0049\u0050\u0057\u003f\u0066\u007e\u0051\u006c\u007a\u0071\u002c\u0045\u0030\u0040\u003a\u005c\u0065\u0072\u0034\u002e\u0035\u0079\u0055\u0046\u0056\u0027\u0058\u0063\u0079\u0040\u0034\u0024\u006b\u0035\u0054\u0065\u0074\u0035\u004e\u003b\u0075\u003e\u0032\u0039\u004b\u0043\u0049\u0040\u0039\u006c\u0052\u0051\u006d\u0043\u006c\u002a\u002e\u002f\u005a\u002e\u0068\u0030\u0069\u0059\u0078\u005f\u005e\u004b\u007e\u0069\u006b\u005d\u0075\u0078\u004c\u004d\u0038\u0060\u004e\u0063\u0026\u003c\u0023\u0061\u004e\u003e\u005f\u006d\u0046\u0038\u0028\u0077\u0027\u002d\u0070\u007e\u005d\u0044\u0031\u004b\u0066\u0039\u003d\u0046\u0023\u0030\u0055\u0054\u007d\u003c\u0020\u0025\u004e\u0051\u003e\u0059\u0070\u006e\u0069\u0074\u0045\u0073\u004a\u006f\u0023\u0021\u002f\u002a\u0044\u0045\u004f\u0071\u0049\u002a\u0034\u006c\u003a\u0038\u0054\u0047\u003e\u004f\u0070\u0046\u003c\u0020\u007a\u0076\u0039\u007c\u0056\u0069\u004f\u007d\u0055\u0078\u007d\u0069\u005c\u0061\u006f\u0066\u0063\u0051\u003a\u0057\u0048\u0020\u0061\u003d\u003e\u003e\u0031\u0063\u0073\u0051\u0026\u0065\u002a\u0046\u0051\u0041\u0046\u0039\u0047\u002c\u0053\u0073\u0068\u003d\u0046\u003a\u006e\u007b\u005e\u003b\u0076\u0054\u0060\u007c\u0073\u0055\u0025\u005f\u0042\u0074\u004f\u0044\u003b\u0052\u004a\u005a\u0052\u002b\u004c\u005b\u003e\u005b\u0078\u0020\u006d\u002e\u005c\u0069\u003e\u0075\u0039\u0060\u0022\u0075\u0045\u0020\u003d\u005f\u0077\u0050\u0061\u004e\u0057\u0059\u0053\u006c\u0050\u0038\u0040\u0054\u004f\u0070\u005e\u006a\u004e\u004f\u003f\u002f\u0025\u0050\u004b\u0049\u0020\u006a\u004c\u0039\u004d\u003d\u0078\u004f\u0025\u0052\u0034\u006c\u0025\u0079\u0054\u0064\u0045\u002a\u0052\u0068\u003c\u005f\u0056\u0024\u0077\u0037\u0036\u0029\u0030\u0074\u0057\u0042\u0063\u0031\u0071\u0059\u002e\u003e\u0063\u0066\u0027\u005a\u003d\u002a\u007e\u0041\u0047\u005e\u006a\u002d\u0066\u004d\u003b\u0026\u002d\u0036\u0032\u0040\u0039\u0021\u0056\u0053\u002d\u0055\u0021\u0073\u0056\u0050\u007e\u0034\u0033\u0035\u002f\u004d\u004b\u0055\u006f\u007d\u002d\u0030\u0020\u004c\u005c\u0037\u006e\u003f\u0025\u0067\u0062\u0025\u004b\u0049\u005a\u0061\u004f\u0054\u0049\u0030\u0029\u006d\u0050\u005c\u0079\u005d\u006b\u0028\u0035\u0046\u0078\u0067\u002f\u004e\u0049\u0042\u0022\u0055\u0028\u0024\u0056\u004a\u003a\u0049\u0037\u0059\u0036\u0055\u0067\u004d\u0076\u0077\u0028\u0032\u0065\u0065\u0061\u0076\u0067\u0023\u0070\u0062\u007e\u003c\u0040\u0047\u0036\u002b\u0034\u003e\u005f\u003a\u0048\u002b\u0060\u0024\u003e\u0027\u002f\u0024\u0059\u0053\u0060\u0029\u0073\u0053\u0061\u0074\u006a\u0072\u0043\u007a\u0038\u004e\u004a\u0028\u0072\u0068\u0039\u0070\u003e\u0030\u0027\u0025\u0039\u0028\u0049\u0045\u0043\u003a\u0065\u003a\u003f\u006a\u0063\u0029\u0062\u002e\u005e\u0064\u0023\u0042\u0065\u006e\u002a\u003f\u006d\u005a\u0073\u004b\u006e\u007c\u006c\u0031\u0034\u0059\u007a\u0053\u005a\u004c\u004f\u002d\u004e\u0035\u0025\u006e\u005b\u007d\u0031\u0056\u0053\u0032\u0023\u0029\u004b\u002a\u0058\u0072\u0054\u006a\u0055\u0052\u0033\u005c\u0027\u0054\u0027\u004f\u0026\u0069\u0063\u0067\u0058\u006a\u0046\u0026\u0066\u004f\u0078\u005b\u002f\u0044\u004a\u006c\u0054\u0077\u0078\u0035\u0024\u0077\u0074\u0023\u0026\u002a\u0070\u0026\u002a\u0033\u004e\u0031\u0037\u007e\u004b\u0059\u0031\u0020\u0071\u004e\u0050\u006d\u0048\u007b\u003b\u0033\u0032\u0068\u0065\u0043\u007b\u002b\u0024\u0052\u0035\u0030\u0028\u004f\u003a\u0029\u0030\u002b\u0024\u0058\u0023\u0066\u002f\u005b\u002a\u0070\u0057\u0050\u0022\u003a\u0040\u0046\u005a\u0055\u0037\u0023\u0033\u0057\u0059\u007d\u003e\u005d\u0055\u003f\u0035\u002c\u003c\u0079\u005d\u0069\u005e\u006a\u007b\u0065\u006b\u0033\u0056\u007c\u0043\u0029\u006c\u005c\u005e\u0075\u0072\u0024\u006a\u0069\u003b\u0026\u002a\u0030\u006f\u007a\u0059\u005b\u007b\u0049\u0064\u003e\u0023\u0070\u007b\u0058\u0027\u0043\u0060\u0078\u0033\u0051\u002e\u0039\u0035\u003b\u0079\u0038\u002e\u0053\u004b\u006b\u0045\u0046\u0054\u0031\u007e\u0047\u005b\u0045\u003b\u004a\u0053\u0039\u0023\u0079\u003d\u0062\u004b\u0032\u005b\u0031\u0025\u004c\u0078\u003d\u0029\u003d\u0077\u003b\u0022\u004b\u005d\u003d\u0036\u0051\u0059\u0071\u0075\u0069\u0041\u0058\u003f\u0079\u005d\u0070\u0040\u0052\u004a\u002e\u0054\u004a\u006e\u0027\u005d\u0069\u006d\u0070\u003c\u007b\u0063\u002a\u007d\u0052\u002a\u0050\u0071\u003b\u0024\u007a\u006a\u006d\u0043\u0027\u0079\u003b\u0036\u0070\u0027\u0054\u002c\u0035\u0022\u0065\u007e\u003e\u0049\u0070\u0068\u0066\u005b\u0061\u0029\u005f\u007b\u0043\u0046\u003e\u0046\u005c\u005c\u0058\u0024\u0035\u0044\u0077\u003a\u0041\u0050\u0057\u004b\u003e\u002b\u0058\u0025\u002a\u0023\u006b\u0055\u0066\u0061\u0024\u0063\u0055\u0043\u0049\u0050\u0063\u0070\u0042\u006b\u002d\u0078\u0060\u003c\u0054\u0072\u0072\u006a\u0054\u0024\u0032\u0050\u0041\u003e\u0051\u0064\u0062\u0050\u0038\u002b\u0033\u0022\u002c\u003f\u0025\u004d\u0057\u0026\u007c\u003e\u004a\u0029\u0026\u0050\u003f\u0036\u0078\u005b\u0074\u0044\u003c\u007d\u0049\u002e\u0064\u003c\u0035\u0054\u005e\u0076\u0041\u0069\u007e\u0051\u0057\u002a\u0043\u002b\u007c\u0070\u0069\u0078\u0041\u0074\u0046\u005b\u0039\u006b\u0069\u005f\u006e\u006d\u0056\u0031\u0060\u0070\u0037\u0070\u0054\u006e\u0045\u004f\u002d\u007a\u0062\u0027\u0070\u0044\u0052\u002b\u004b\u0071\u0079\u0048\u005e\u006b\u002b\u003e\u0074\u0032\u0069\u002f\u0042\u0049\u0069\u0062\u0029\u0072\u0079\u004a\u007a\u0079\u0043\u006d\u003b\u0051\u0037\u0035\u0062\u007b\u0051\u0022\u0063\u0077\u005c\u007d\u0047\u002a\u0062\u0045\u0059\u0055\u0076\u0061\u0065\u007a\u0049\u0060\u0069\u0049\u0061\u003c\u004d\u0073\u0021\u0055\u0029\u0076\u0064\u0051\u0046\u0061\u0069\u006c\u0054\u0073\u0059\u0079\u0022\u0079\u0076\u0067\u002a\u003b\u0056\u0029\u0068\u0028\u0035\u006f\u0072\u004b\u0038\u0043\u0051\u006b\u0034\u002d\u0029\u005e\u0032\u0054\u0053\u0056\u0049\u0049\u004d\u0059\u0023\u0048\u0021\u0077\u0072\u0077\u0049\u007c\u005f\u0066\u006b\u005b\u0044\u0041\u006e\u0045\u0068\u0039\u007c\u0049\u0056\u0056\u003c\u0028\u003e\u0027\u0054\u002d\u004c\u0064\u0076\u005e\u0032\u0060\u0052\u0061\u0064\u0057\u002d\u0021\u0025\u0059\u006c\u0049\u0020\u0063\u002b\u0069\u0076\u005d\u0050\u003b\u005c\u006d\u006b\u0065\u0059\u0059\u005b\u0050\u005c\u007e\u0077\u0025\u004d\u0039\u0046\u0055\u0020\u006d\u004e\u0075\u005f\u0022\u0030\u004d\u0075\u0051\u002f\u0022\u004e\u003a\u0044\u006e\u005f\u0041\u007d\u007c\u0076\u0041\u0044\u003e\u002a\u003c\u006c\u0055\u0063\u003b\u007b\u007d\u0031\u0042\u0029\u0025\u0042\u003c\u0066\u003e\u0040\u005b\u004d\u005e\u0073\u0031\u002f\u002f\u0068\u007e\u0078\u0042\u0053\u002b\u0062\u007d\u0050\u0050\u0035\u003b\u0062\u0040\u0026\u0021\u005d\u002a\u0058\u005e\u0050\u0038\u005d\u003a\u005a\u0049\u006f\u005c\u0025\u0034\u005a\u0029\u0070\u007a\u007d\u007c\u0062\u0031\u0074\u0039\u006f\u006f\u0029\u0068\u003c\u0075\u006a\u006a\u003c\u0040\u0073\u0079\u004e\u0074\u0031\u0049\u004d\u0059\u0031\u0056\u007e\u005f\u0058\u002c\u0066\u004a\u0078\u004a\u0059\u007d\u0037\u006a\u003c\u0044\u002c\u005b\u0024\u0075\u004c\u0053\u0074\u003b\u0063\u0044\u002f\u0042\u007b\u0047\u0057\u0063\u0071\u003f\u0062\u002a\u0046\u0038\u0036\u0032\u002a\u0026\u0050\u002e\u006d\u0038\u0034\u003e\u003e\u002f\u0047\u002c\u0061\u003a\u002d\u0023\u004f\u0064\u0063\u0020\u0045\u0044\u006c\u0056\u003a\u0071\u0046\u0050\u0068\u0057\u0027\u0064\u0028\u0050\u0062\u0065\u006a\u005a\u002c\u0034\u0068\u0073\u007d\u0059\u003b\u0039\u0067\u0067\u003f\u0031\u0065\u0053\u0023\u0058\u007c\u0069\u007e\u0042\u0027\u0077\u0026\u0069\u0059\u0057\u002b\u0054\u0066\u0062\u007d\u003d\u006a\u0040\u0044\u0062\u0026\u002d\u005c\u0072\u004b\u0074\u0075\u0077\u004d\u007c\u0028\u005a\u0068\u002a\u0071\u007d\u0072\u0072\u0056\u0049\u0020\u007d\u0076\u0070\u003e\u0039\u003e\u002a\u0031\u0076\u0021\u004d\u0031\u006f\u006c\u002b\u0021\u0045\u006d\u0078\u0052\u002d\u006d\u0031\u006c\u0063\u006a\u007a\u0054\u0075\u0060\u005f\u002d\u0036\u0070\u0033\u002d\u007a\u0044\u003a\u0076\u0020\u0020\u004e\u0046\u002e\u006b\u0045\u0034\u004d\u0029\u005a\u006e\u007c\u0078\u0029\u0038\u0031\u0076\u005d\u0058\u002f\u0076\u0033\u0021\u0060\u0075\u005f\u0047\u0035\u006a\u0067\u002d\u002c\u0028\u0033\u0048\u0074\u004f\u0063\u0024\u0042\u006b\u0051\u002a\u0031\u0077\u0027\u004c\u0026\u0041\u0052\u0067\u002d\u0020\u0078\u0036\u0073\u003c\u002a\u0068\u003e\u0075\u0049\u0048\u0055\u0024\u006b\u0024\u0069\u0055\u0070\u007a\u007a\u0053\u0071\u006f\u004f\u0074\u0063\u0024\u0070\u0033\u007d\u0068\u005e\u002d\u003e\u005b\u0061\u0032\u003a\u006a\u0064\u005e\u0074\u0059\u0075\u0061\u0076\u0039\u006a\u0031\u006a\u003e\u0035\u0021\u006f\u004c\u0044\u0040\u004a\u0041\u0032\u0061\u0078\u0074\u0048\u0060\u0050\u0040\u0064\u0028\u0068\u0046\u004e\u0065\u005e\u0056\u0049\u005e\u002a\u0072\u0049\u0029\u0034\u0075\u0036\u004c\u0059\u002c\u0063\u004f\u006d\u0032\u0051\u0020\u004a\u0026\u0043\u0079\u003e\u0065\u002b\u006a\u0041\u006c\u0052\u0050\u0043\u004a\u0079\u0048\u005f\u0042\u004a\u002f\u007e\u0038\u006e\u006b\u007c\u0078\u0053\u0038\u0066\u0047\u0067\u007a\u007a\u0052\u0021\u0028\u002c\u004c\u0041\u0036\u0038\u004a\u0069\u0035\u0040\u004c\u0064\u0053\u002c\u0053\u006c\u0023\u0047\u0034\u0071\u0043\u0039\u0037\u0055\u0076\u0061\u0025\u0023\u004e\u0051\u0070\u0031\u002f\u0050\u0026\u0032\u0025\u0073\u0054\u002b\u0030\u0044\u004f\u0073\u0052\u0022\u006c\u002d\u0026\u003d\u005b\u0042\u004a\u003e\u003c\u005b\u003f\u006a\u006d\u0049\u007d\u0070\u0043\u0031\u0045\u002f\u004d\u0042\u0038\u0029\u003a\u005e\u003f\u0034\u006a\u0052\u002a\u0079\u007a\u0031\u005a\u0067\u0024\u0075\u0026\u0026\u0027\u0058\u004c\u0047\u0040\u006c\u0031\u007b\u0033\u006e\u0023\u0056\u003f\u0045\u0020\u007a\u0045\u0022\u0049\u0069\u0067\u003d\u0054\u0077\u0067\u006b\u0050\u002e\u0034\u0033\u0026\u0054\u0020\u0070\u0036\u0041\u0075\u0041\u004c\u0059\u0033\u004d\u0064\u0022\u002c\u004e\u007b\u0070\u005f\u0038\u005e\u0049\u0042\u0027\u004a\u004f\u0041\u0066\u0063\u0059\u0078\u002c\u0071\u003b\u0046\u006c\u0038\u007a\u002c\u005e\u002e\u007a\u006d\u004c\u0058\u003b\u0033\u0078\u0053\u0027\u0061\u0073\u007e\u006c\u0059\u0032\u0043\u0078\u007c\u004d\u0058\u006a\u0026\u006d\u006f\u002d\u0053\u0048\u003d\u0077\u0033\u0077\u0064\u0042\u0079\u0039\u006d\u0024\u0038\u0039\u003b\u0036\u0033\u0072\u0042\u007d\u004c\u0079\u0066\u0064\u0060\u004d\u002d\u006c\u0057\u0021\u0049\u0021\u0023\u0068\u005e\u005d\u0047\u003e\u006d\u0055\u0046\u0049\u002c\u007a\u0041\u006a\u0025\u0027\u0057\u0021\u002a\u004f\u0046\u0022\u007d\u004a\u0048\u004f\u002b\u0042\u0053\u006c\u0060\u007b\u0054\u0063\u0041\u006d\u002d\u0060\u0021\u0042\u0053\u0054\u0056\u0051\u003a\u0042\u0024\u003d\u0061\u0065\u0047\u0043\u0051\u007b\u0062\u002e\u002e\u0048\u0067\u003f\u0064\u0054\u0036\u002a\u006d\u0057\u004b\u003e\u0048\u0070\u0034\u0039\u0030\u004d\u002b\u006b\u0072\u006d\u004d\u007a\u002b\u002f\u0027\u0022\u0060\u0057\u002b\u005e\u004a\u0063\u0060\u0041\u0029\u007a\u0075\u0027\u0044\u007a\u0070\u005c\u0051\u0047\u0032\u005e\u007d\u0045\u0020\u0037\u0045\u0039\u0063\u0049\u004f\u006c\u006a\u007d\u0043\u0031\u0074\u0037\u002c\u002b\u0031\u0024\u0062\u0078\u006a\u0026\u0079\u007c\u0055\u0038\u0050\u0073\u005e\u003f\u003e\u0032\u003c\u0078\u0042\u0060\u0057\u006f\u002a\u0063\u002b\u0067\u0054\u005e\u0046\u0045\u0079\u003e\u003d\u0026\u002f\u0037\u007c\u0073\u0052\u002d\u0053\u0076\u003a\u0077\u0069\u006a\u0043\u007a\u003d\u0066\u0038\u0021\u007a\u0057\u003c\u007e\u005e\u0020\u007d\u004c\u002e\u0045\u006c\u0066\u0077\u005d\u0048\u0057\u0060\u0052\u0021\u003f\u002c\u0056\u0061\u0051\u0072\u0028\u006c\u0063\u003f\u006b\u0027\u0039\u007c\u0079\u0057\u005e\u0027\u0056\u0038\u006b\u0032\u006b\u007c\u0040\u005a\u004b\u0075\u002f\u0060\u0052\u0052\u0049\u0025\u004c\u0066\u002c\u0020\u004c\u006f\u005e\u0030\u007b\u006a\u0073\u007d\u0022\u004d\u0033\u003a\u006f\u0058\u0072\u006c\u0071\u004f\u0032\u006d\u004d\u0058\u007a\u007e\u004d\u0070\u0057\u0022\u0034\u005f\u004f\u0078\u0064\u0051\u007e\u0026\u003a\u0021\u002d\u0021\u0020\u0041\u002e\u0038\u002d\u0078\u003a\u0032\u0052\u0046\u0064\u0050\u0058\u007a\u0068\u0052\u006d\u006a\u007a\u0051\u003f\u005c\u0063\u003a\u0069\u0065\u0062\u0039\u0031\u0048\u005e\u004a\u003a\u0038\u0051\u0073\u0034\u0048\u0035\u0046\u0068\u007b\u0055\u0026\u0024\u002b\u0031\u002e\u0038\u0049\u0020\u006c\u0051\u0050\u0062\u0059\u0069\u0062\u0046\u0044\u0074\u0059\u007c\u003b\u0060\u003a\u0027\u0026\u0029\u004f\u0075\u0075\u003d\u0047\u007e\u0063\u0054\u005b\u003b\u004a\u0042\u0050\u0036\u003b\u0055\u0044\u0026\u0048\u002d\u006d\u005b\u0059\u002c\u0045\u006a\u0035\u0070\u0039\u006e\u0075\u007a\u0035\u0034\u0065\u0062\u003c\u004f\u005c\u0060\u0043\u0068\u006d\u007a\u003f\u0076\u0028\u006c\u0026\u0050\u0056\u0052\u0039\u006e\u0028\u0053\u002e\u004f\u0029\u006e\u0048\u004f\u0073\u004f\u002c\u002a\u004f\u0026\u005b\u0032\u005e\u0032\u003f\u0030\u0034\u0050\u005c\u0057\u0023\u002e\u004c\u003c\u0022\u0079\u0064\u0030\u0050\u0079\u002a\u0056\u0055\u0040\u0037\u0035\u006b\u0039\u003a\u0062\u0043\u0041\u005c\u004e\u0074\u0034\u005d\u002b\u006f\u0026\u002d\u0040\u0043\u002f\u0042\u0044\u007d\u0049\u0030\u0047\u0065\u0054\u004a\u005d\u0051\u0056\u004c\u0066\u005b\u0068\u005e\u007e\u004a\u0046\u0063\u003c\u0042\u007b\u002e\u005d\u003a\u002a\u0066\u0038\u0029\u0043\u007d\u0049\u0048\u0034\u0035\u0030\u0025\u004f\u002a\u0041\u0072\u0047\u0050\u0062\u006a\u0047\u0048\u005d\u007d\u0048\u0061\u006a\u005b\u003f\u0069\u0065\u003a\u0040\u0048\u007b\u0069\u0043\u0073\u0038\u003f\u0026\u0029\u0071\u0070\u0061\u0023\u005d\u0078\u0067\u005c\u0056\u007e\u0074\u005f\u007d\u002b\u005e\u0077\u002e\u0052\u0023\u0072\u007d\u0073\u0036\u003f\u0026\u0079\u007e\u0073\u0030\u002d\u0062\u0050\u0036\u0064\u003c\u0041\u007a\u0042\u0063\u0022\u006b\u004e\u0022\u0041\u006b\u003c\u0043\u0069\u0073\u0057\u004c\u006e\u007a\u0028\u007d\u0044\u0025\u0039\u004f\u0041\u0037\u0056\u0051\u005f\u0061\u006c\u0024\u0073\u0055\u006a\u0064\u007c\u0032\u0042\u0054\u0038\u0076\u004d\u007b\u0056\u003a\u003f\u0055\u0041\u0034\u004a\u0057\u0034\u004e\u002a\u004d\u0048\u002f\u0037\u002a\u0052\u0074\u003e\u0041\u0072\u007a\u006c\u0029\u0025\u005e\u0028\u0032\u007b\u002f\u0033\u002a\u0063\u0035\u0020\u0022\u0078\u002f\u003b\u0044\u0029\u0029\u0040\u0050\u0033\u0048\u0025\u0075\u0057\u0020\u003e\u0030\u003c\u0040\u005f\u0064\u004e\u0027\u002f\u0072\u003e\u0042\u0038\u0049\u0065\u0051\u0073\u0066\u0076\u0036\u003e\u0048\u0052\u005c\u006c\u0052\u0023\u0025\u0030\u0030\u0059\u0035\u005e\u0044\u006d\u0022\u007d\u0051\u004e\u0044\u0026\u0077\u0053\u0057\u0053\u0028\u004d\u0049\u0029\u006e\u006d\u0053\u002e\u005a\u0076\u0069\u0021\u0027\u0064\u0032\u003c\u0041\u0039\u003c\u0061\u003b\u0053\u0071\u0043\u0042\u006a\u003a\u0073\u0079\u0028\u006f\u0041\u002c\u0067\u0022\u0033\u003a\u0033\u0071\u0055\u0025\u006b\u0057\u002e\u0075\u0055\u003a\u005b\u005c\u007b\u0046\u0037\u005c\u005d\u0054\u0052\u0040\u0033\u006c\u005c\u0036\u002e\u006f\u0040\u003b\u0036\u0036\u0022\u006c\u0037\u002a\u0028\u005e\u0079\u006f\u0072\u0047\u004d\u0066\u0032\u002e\u0062\u002a\u0075\u0033\u0048\u0041\u0046\u0025\u0022\u007a\u006a\u0060\u0071\u0062\u0027\u0074\u0056\u0021\u0078\u004a\u003c\u0028\u002c\u0031\u0036\u007e\u006d\u0037\u002b\u0040\u0075\u003d\u0062\u0073\u006a\u006b\u0033\u007d\u0054\u004d\u0020\u0038\u0066\u002e\u003b\u005b\u0033\u006c\u0060\u0043\u002b\u005a\u0054\u0022\u004d\u004d\u003c\u0048\u0062\u005d\u0050\u0047\u0066\u003a\u0034\u005b\u0022\u0063\u004c\u007d\u006a\u006b\u0027\u0047\u002b\u005d\u006a\u0073\u005f\u004e\u0077\u0033\u005f\u0059\u0032\u0065\u006c\u004e\u0038\u0021\u0034\u004b\u0061\u0068\u0045\u006e\u0037\u004a\u005c\u0059\u0045\u004c\u006d\u002c\u0077\u003d\u006f\u002f\u002c\u0079\u004d\u006a\u004e\u0050\u002d\u002b\u0021\u0039\u003c\u0037\u0052\u004b\u0066\u0064\u0028\u003a\u0070\u0021\u004e\u0064\u005b\u0050\u0036\u003f\u006a\u006b\u005d\u0042\u0071\u0039\u0048\u0067\u0026\u0079\u003c\u0052\u003a\u004a\u007e\u0074\u002e\u002e\u0026\u002d\u007b\u0049\u0035\u0037\u005c\u002e\u0070\u0054\u0054\u005a\u0067\u0053\u0054\u0063\u002e\u0024\u005c\u006c\u0028\u0065\u0056\u0040\u0028\u0024\u0062\u0027\u003b\u002b\u0070\u003f\u0076\u003e\u0041\u0076\u002b\u0034\u0076\u0065\u0072\u0022\u0065\u006b\u0057\u0037\u003e\u006c\u0059\u0052\u0050\u0035\u0043\u0030\u0033\u0078\u005f\u0036\u006b\u0060\u0059\u0021\u0024\u0033\u0064\u0029\u0048\u006f\u0028\u006d\u0027\u0042\u002d\u0062\u0054\u0034\u002c\u0057\u006a\u003a\u0045\u0031\u0064\u007e\u005d\u0024\u0071\u0034\u002b\u0053\u0061\u004a\u002a\u0024\u0026\u0045\u0035\u0064\u003f\u0048\u0031\u0064\u007c\u002f\u002e\u0044\u0074\u004c\u002d\u0076\u0066\u0024\u0068\u007e\u002c\u004b\u0065\u0051\u0061\u0078\u004b\u004c\u0037\u0055\u0052\u007d\u0032\u0030\u006e\u0029\u0023\u006b\u003c\u006b\u007d\u0034\u0032\u0049\u0040\u0061\u002a\u0059\u0054\u0049\u0021\u004a\u0068\u0039\u0049\u0074\u004f\u003d\u004d\u0044\u003b\u0041\u005b\u004f\u004f\u003d\u003b\u006a\u0033\u007e\u005c\u002c\u0026\u006a\u0037\u006a\u0062\u0050\u004b\u0064\u0067\u006f\u0030\u002d\u002e\u0029\u0030\u0021\u0069\u006d\u0028\u0041\u0067\u0070\u007a\u0021\u0059\u0077\u0074\u002e\u0020\u0069\u0028\u005c\u0061\u006b\u003c\u0030\u004d\u0046\u006e\u0055\u0057\u0064\u0056\u0038\u002c\u0043\u0045\u0037\u003c\u0059\u007d\u002d\u0029\u007d\u005c\u0051\u0053\u0046\u002d\u0042\u005f\u006e\u006b\u0052\u0058\u0034\u0053\u0034\u0073\u0069\u0026\u007c\u0075\u0044\u0020\u0055\u003e\u003a\u005b\u0079\u0076\u0056\u0076\u004d\u006c\u0040\u006e\u0021\u0045\u004c\u003f\u0052\u004a\u0065\u0035\u0021\u0046\u0039\u0043\u003d\u0024\u0074\u0043\u003a\u0045\u0061\u0079\u0061\u0025\u002f\u0034\u0029\u0063\u0055\u0070\u002a\u007b\u0075\u0064\u0039\u0026\u007c\u007b\u004c\u003c\u0042\u0050\u0049\u0079\u002f\u002c\u004c\u0059\u005c\u0030\u0042\u0067\u0035\u0065\u0059\u004d\u0020\u0049\u0079\u003f\u0055\u0068\u0069\u006d\u0062\u003f\u0058\u0023\u006a\u0061\u0046\u0065\u004a\u004c\u004f\u002f\u0036\u0061\u0078\u0028\u005d\u0044\u007a\u0044\u007e\u0024\u007c\u0065\u007e\u005f\u0059\u0033\u0051\u003d\u0052\u0066\u0074\u0037\u006f\u0064\u0053\u0066\u005c\u0056\u0040\u007b\u003c\u0067\u0052\u0052\u0040\u0066\u004a\u0073\u004e\u0059\u0046\u0064\u0075\u0074\u0039\u005c\u0021\u0028\u0033\u0066\u007a\u0035\u0061\u0076\u004c\u0057\u0061\u0069\u0044\u0056\u0061\u0062\u0029\u0064\u006f\u003f\u0070\u0049\u003a\u003e\u003f\u002d\u003f\u0036\u007d\u0079\u006e\u003d\u0038\u0049\u007e\u005e\u006d\u003e\u004a\u002c\u0063\u006b\u004e\u0059\u0020\u0064\u0042\u004e\u005b\u004a\u0065\u0038\u005f\u0041\u002e\u004b\u007e\u0063\u0049\u0078\u006f\u0037\u0048\u0032\u0076\u005e\u0068\u0046\u0044\u0021\u007e\u0058\u0047\u0048\u0060\u0052\u0066\u002b\u0023\u005c\u006f\u0027\u0028\u007e\u006f\u0024\u0049\u0062\u006f\u0063\u0079\u006b\u0078\u0069\u0036\u0042\u0055\u004a\u002a\u0067\u002b\u0021\u0079\u0077\u0034\u0069\u0035\u004e\u002c\u0025\u002f\u002b\u003f\u0033\u0050\u0026\u0047\u0072\u0037\u0027\u0048\u0042\u0063\u0026\u005a\u0077\u0047\u0045\u0043\u0035\u0049\u0068\u0034\u0026\u004a\u0022\u003e\u005e\u0032\u0035\u0061\u0034\u004f\u0028\u0045\u0025\u0071\u003f\u0079\u0039\u0062\u0034\u004b\u006a\u004d\u0043\u0024\u0060\u006f\u0065\u0041\u0057\u0035\u003f\u003d\u0046\u0024\u0024\u0078\u0023\u003b\u007a\u0028\u003e\u0051\u0061\u004b\u007d\u0028\u0074\u0063\u004c\u0045\u0041\u0038\u002d\u0075\u003d\u002a\u004d\u003a\u0052\u0021\u0023\u003a\u0029\u0063\u0061\u006b\u0043\u007d\u0040\u007a\u0051\u0060\u005f\u003e\u0062\u0074\u0050\u0031\u0050\u0030\u004e\u002e\u0078\u007c\u003f\u0052\u0078\u0065\u007e\u0042\u005a\u004e\u0041\u0030\u0060\u0044\u0063\u0041\u002b\u0021\u0051\u0074\u004f\u0073\u0031\u002c\u0044\u0050\u0075\u004c\u0068\u007b\u006d\u0050\u007d\u005e\u0060\u0064\u006f\u0061\u0061\u0055\u0063\u0053\u002a\u004f\u0068\u0045\u003d\u0061\u0024\u0072\u0059\u0051\u0064\u0059\u0069\u003c\u0059\u005d\u006c\u005d\u006d\u007b\u0029\u002f\u0049\u0045\u0078\u0077\u002a\u006c\u007b\u0031\u0034\u0077\u003f\u002f\u0035\u004e\u007e\u002b\u006c\u0033\u0021\u004d\u0025\u0020\u0061\u005c\u0076\u0042\u005e\u0063\u0062\u0073\u0029\u0074\u0040\u0051\u007a\u0029\u0071\u0053\u0067\u0078\u0049\u0027\u0036\u0053\u0052\u0056\u005d\u006f\u0039\u0052\u0036\u004d\u007a\u0020\u0057\u006f\u0024\u0022\u0055\u0070\u0024\u0043\u0075\u004a\u002e\u006e\u0063\u0040\u006a\u006c\u0069\u002f\u0025\u002c\u003c\u0071\u0062\u0047\u003e\u0059\u002d\u0078\u002c\u003f\u003d\u0076\u0042\u0047\u0073\u007d\u0061\u0039\u003d\u0059\u0036\u0020\u006c\u0076\u0034\u0048\u004f\u002d\u0029\u003a\u0029\u003a\u002b\u002f\u003c\u0041\u004f\u0026\u0077\u0056\u002b\u006e\u007a\u0070\u0052\u0052\u004f\u0057\u0038\u004c\u0050\u007d\u0078\u0052\u0064\u002b\u007d\u0064\u0065\u0047\u003a\u003c\u0037\u004f\u005c\u003e\u0042\u0045\u005b\u0040\u004d\u006f\u006f\u003b\u0033\u0050\u0066\u0025\u0048\u0078\u0023\u0069\u003f\u003d\u0026\u0062\u0061\u0023\u0069\u004c\u0073\u0053\u0067\u004c\u0059\u003e\u0079\u003c\u0022\u0051\u0070\u002c\u002e\u0030\u0026\u003a\u005b\u0063\u002e\u0076\u0077\u003a\u006a\u0061\u005c\u0030\u0024\u0022\u006c\u003b\u0075\u0054\u007b\u006f\u0070\u0068\u0043\u005f\u006d\u0077\u0041\u0032\u004b\u0049\u002b\u002b\u0020\u0050\u0065\u002b\u0077\u0060\u0062\u0055\u007b\u006e\u006e\u0056\u0073\u0034\u0029\u005d\u0049\u005b\u007c\u0053\u003b\u002d\u0078\u007c\u0057\u006a\u0067\u005c\u0026\u0030\u003c\u005b\u0069\u0043\u004a\u0052\u0045\u003f\u0042\u0062\u005e\u002b\u003c\u0034\u0050\u007b\u0068\u004f\u0074\u0039\u0033\u0078\u004e\u007e\u0069\u0061\u0040\u0021\u0027\u0070\u0075\u0047\u0064\u0023\u003b\u004f\u0059\u0039\u005a\u0055\u0054\u005a\u0041\u003b\u004d\u0049\u0068\u0042\u0022\u003f\u0033\u0038\u0078\u0030\u003b\u0027\u0057\u007b\u0078\u0021\u0059\u0052\u007d\u003c\u0063\u0031\u0054\u0062\u007e\u0068\u007b\u006d\u006d\u0048\u006b\u0030\u005f\u003e\u0070\u0072\u0020\u005f\u007b\u0064\u0077\u006d\u0048\u0031\u002a\u007d\u0039\u006f\u0037\u0031\u005d\u0051\u003f\u0074\u0076\u004c\u0028\u004a\u003e\u0038\u003c\u0067\u0076\u0078\u0054\u003b\u0025\u0045\u0073\u0034\u0032\u0069\u004a\u0029\u0064\u0046\u0078\u0063\u0077\u0050\u0020\u0046\u0059\u006e\u0029\u0044\u0063\u0027\u004e\u003c\u002f\u005b\u0036\u005c\u003e\u0026\u0033\u0055\u0032\u0020\u002c\u0025\u002c\u0056\u007a\u0059\u0067\u003e\u0022\u0037\u0047\u0033\u0039\u0053\u007b\u0079\u0053\u0050\u007e\u0032\u006d\u002e\u003f\u0071\u0037\u002a\u0025\u0064\u003c\u0059\u0027\u0079\u0047\u004f\u005d\u002c\u0042\u006d\u0045\u0029\u0063\u003a\u006e\u0022\u007e\u007c\u0050\u0024\u0065\u0058\u0077\u0029\u004a\u0075\u0066\u007b\u0046\u0042\u0053\u0047\u0046\u0032\u0027\u0039\u0057\u0042\u006b\u0038\u0052\u003a\u002c\u0070\u0057\u0039\u003d\u0070\u0024\u0033\u0058\u004e\u007c\u007b\u007c\u006b\u0023\u003d\u0051\u002c\u004b\u002c\u006a\u0072\u0032\u0060\u002b\u006a\u004b\u0067\u003b\u004a\u005f\u0055\u0020\u007d\u002f\u0048\u006e\u0079\u006a\u0023\u003f\u0055\u0025\u002c\u0027\u0033\u005f\u0070\u0063\u0023\u004d\u0058\u0041\u004b\u0047\u006f\u0079\u003c\u0066\u0041\u002b\u0030\u0030\u0078\u0027\u0057\u0021\u005a\u005a\u0052\u0025\u0032\u0068\u002f\u004d\u0050\u0030\u0068\u0047\u007b\u004d\u002e\u0024\u007e\u006e\u006b\u002d\u0023\u0043\u006d\u003b\u002d\u0079\u0063\u004d\u0058\u006a\u0071\u0041\u0051\u0027\u0076\u007c\u007c\u007a\u007a\u007d\u0026\u0026\u0065\u0034\u004b\u0023\u002b\u0033\u003e\u003d\u0042\u003f\u0076\u006c\u0022\u0034\u0034\u003e\u0024\u0062\u004a\u006a\u002d\u005a\u005e\u005a\u005d\u0047\u0036\u0065\u003a\u0023\u0058\u005f\u005a\u0022\u0045\u006b\u007e\u0021\u0046\u002f\u002b\u0052\u0054\u007a\u0074\u0050\u002b\u004b\u004a\u0038\u002e\u0022\u0028\u005e\u004f\u0064\u004c\u0045\u002f\u0079\u004f\u0057\u002b\u0060\u002e\u0030\u005b\u0065\u003f\u0045\u004d\u002d\u0031\u004b\u0073\u0066\u005b\u007a\u0066\u0023\u005c\u0078\u003d\u0067\u0062\u0029\u0039\u0020\u0066\u0074\u0032\u006c\u0049\u002a\u0070\u006d\u002b\u003a\u0044\u003f\u0031\u005f\u007b\u0071\u0029\u004e\u003f\u003f\u0067\u0025\u0037\u0054\u004e\u007a\u0058\u004a\u003a\u0047\u003b\u004a\u0034\u0071\u0057\u0070\u0033\u0069\u002c\u0074\u0059\u005a\u005b\u003b\u005c\u0033\u003b\u0062\u0068\u006a\u005a\u0062\u006d\u0039\u007d\u0032\u0023\u0079\u0058\u0027\u003b\u004e\u005f\u0020\u003e\u002e\u006b\u0067\u0024\u0062\u0056\u0052\u004d\u005d\u0032\u0070\u0072\u0064\u0060\u0075\u0032\u0023\u006c\u0071\u0058\u0045\u0059\u0038\u0040\u0034\u0074\u007e\u0064\u0049\u004f\u0051\u003e\u0022\u003d\u003b\u0076\u0072\u002c\u002f\u002b\u0061\u004d\u007b\u0047\u006e\u004e\u007e\u006d\u0073\u002e\u004d\u004c\u005d\u0078\u0068\u004e\u004a\u0047\u007b\u0060\u002e\u002b\u004e\u0043\u004b\u002e\u007c\u004d\u003d\u004b\u0079\u0025\u0024\u0051\u007c\u005a\u006b\u0038\u0074\u0049\u0021\u0070\u002a\u005a\u0057\u0065\u0052\u0056\u0041\u0069\u0079\u006c\u0022\u002b\u005b\u0069\u002c\u0073\u0078\u002f\u0067\u0030\u0030\u003b\u0023\u0048\u0078\u002b\u0055\u002c\u0021\u0045\u003e\u0051\u0054\u0020\u0026\u002d\u0037\u003f\u0026\u005e\u0045\u005a\u0043\u004c\u005f\u0058\u0036\u002d\u0047\u0077\u0036\u0074\u0041\u0047\u003c\u007e\u0070\u0065\u004d\u002c\u003d\u0035\u0031\u005f\u0065\u0072\u0056\u002b\u0021\u0031\u0038\u003a\u0075\u003a\u006a\u0067\u0070\u007a\u0060\u0021\u0021\u0031\u0057\u003d\u0031\u007e\u0038\u002e\u006f\u0068\u006e\u0047\u0032\u0072\u0021\u0049\u003c\u0037\u004f\u002b\u007b\u0073\u0052\u002a\u0062\u0032\u007d\u0062\u005d\u005d\u0047\u0072\u0066\u0071\u0045\u003b\u004b\u003c\u007c\u0032\u0067\u0046\u0065\u006c\u0077\u006a\u005c\u0051\u007b\u0054\u0021\u0059\u003e\u0063\u0039\u0056\u003e\u0061\u003e\u0058\u0033\u003c\u002b\u0030\u003a\u0025\u0022\u0050\u0032\u002f\u0071\u0024\u0049\u005c\u0034\u0077\u0046\u002e\u006d\u005c\u0046\u0044\u0051\u0025\u0031\u003c\u005a\u0076\u006f\u0026\u0026\u0048\u0041\u0053\u005e\u0034\u0057\u0072\u0065\u005e\u0032\u0037\u0076\u004b\u0075\u0057\u005b\u0020\u0071\u003a\u0039\u002f\u0059\u006e\u0076\u0030\u0034\u005f\u0062\u0028\u0046\u006d\u0079\u0027\u007d\u0060\u0026\u006d\u0035\u0059\u0058\u0044\u0073\u003d\u0027\u0058\u006a\u003c\u002f\u0024\u002b\u0024\u0051\u0047\u0035\u0051\u0075\u0035\u0028\u0049\u0035\u0029\u0022\u006d\u0061\u0058\u005a\u0067\u004e\u0036\u0037\u007d\u007d\u0052\u0066\u006d\u006b\u0030\u007d\u0022\u0064\u004c\u0079\u0029\u0074\u005b\u0062\u0047\u0045\u007e\u0024\u004a\u0079\u006a\u002b\u007e\u0054\u0028\u0022\u0070\u0034\u0037\u004d\u0069\u0052\u007a\u004e\u0034\u002e\u0021\u007e\u005c\u0057\u0077\u004b\u003f\u004c\u0041\u0032\u003e\u006f\u0044\u0061\u0040\u0025\u006d\u0063\u003a\u0071\u005c\u0045\u006a\u002d\u0020\u0042\u0035\u0047\u0057\u006c\u0056\u007c\u004e\u0060\u0043\u007b\u0034\u006b\u0043\u007a\u0036\u004a\u0030\u0032\u0042\u003c\u007a\u0059\u006c\u0028\u0031\u005b\u0039\u0026\u0032\u0026\u004e\u0075\u004a\u006f\u006a\u006c\u0030\u0022\u0059\u003c\u0039\u007b\u0072\u0039\u0050\u0057\u005b\u0055\u004b\u0078\u0078\u003a\u0049\u0079\u0043\u002d\u002a\u0038\u004f\u0029\u0023\u003b\u0079\u007a\u0073\u0040\u002d\u0062\u0032\u0021\u0049\u0027\u0073\u0079\u0035\u006c\u004e\u002b\u004e\u003a\u002f\u002b\u0063\u0076\u004a\u005d\u005b\u0047\u0072\u0023\u0057\u005b\u0024\u0027\u0037\u0070\u0058\u0034\u0023\u0038\u0024\u004a\u005b\u0052\u0074\u0023\u0059\u0066\u006d\u003f\u003f\u0037\u0029\u0040\u0039\u002c\u006c\u0022\u0025\u0031\u0069\u006e\u0043\u0033\u0075\u007a\u0034\u0077\u0043\u002d\u0043\u0028\u0045\u0023\u0079\u002c\u0058\u006c\u0062\u0029\u0031\u0067\u002b\u007a\u0069\u005a\u0077\u003e\u0029\u0070\u0062\u0045\u0053\u005e\u007a\u005f\u006b\u005d\u0068\u007a\u004d\u0034\u005b\u0047\u0076\u0029\u0056\u003b\u0072\u004e\u0020\u0074\u002b\u0062\u007a\u0029\u0053\u0043\u004d\u0037\u007b\u003e\u0064\u0077\u0049\u0054\u0072\u0072\u0022\u0059\u0032\u0035\u0041\u0057\u003a\u007d\u0052\u003e\u0032\u0030\u0038\u004b\u0060\u0062\u006c\u0045\u006d\u006e\u0053\u0054\u0029\u0058\u0043\u0021\u004f\u005c\u0058\u002f\u006e\u0023\u0067\u0038\u0039\u0063\u0069\u007b\u002b\u007b\u002d\u007e\u002a\u0061\u0073\u004b\u0036\u002d\u0036\u003a\u003f\u0023\u0066\u005b\u0036\u0063\u005f\u0030\u006d\u0042\u005a\u002e\u002c\u0068\u0063\u0038\u007c\u0075\u0023\u003d\u0063\u0026\u0051\u007e\u0052\u0054\u006c\u0072\u0052\u0066\u004d\u0060\u002f\u004e\u0052\u0077\u0055\u0032\u0037\u005a\u002a\u004d\u002b\u006c\u0039\u007c\u004c\u0061\u0027\u0034\u0050\u0065\u0040\u003e\u007b\u003a\u0060\u0055\u0069\u0063\u003e\u0038\u0030\u0053\u0055\u0049\u0050\u002a\u0037\u006c\u0072\u0063\u003e\u002c\u004f\u0053\u006e\u0051\u0036\u0062\u0036\u004c\u0041\u003b\u0070\u0022\u006c\u0055\u004e\u0040\u0048\u006a\u0054\u0061\u006d\u0061\u0066\u0032\u0068\u004b\u0061\u005d\u007c\u005f\u002c\u004e\u0071\u0070\u0032\u0053\u0063\u0060\u0021\u0031\u0058\u005a\u006b\u007b\u0076\u0058\u0056\u0038\u002b\u0061\u0046\u0071\u0037\u0056\u0036\u0051\u007a\u003b\u0067\u0057\u0031\u0050\u0078\u0024\u0065\u0025\u0051\u006c\u0076\u0050\u0076\u0024\u006d\u007e\u006c\u0024\u003d\u0050\u0069\u0073\u0051\u0020\u0032\u0059\u0028\u0078\u0066\u0053\u0052\u0037\u0071\u0033\u006c\u0049\u0028\u0062\u0077\u0055\u0033\u0031\u005a\u0023\u005b\u006d\u0074\u006a\u0049\u0022\u004d\u0079\u006b\u0044\u003b\u003b\u003a\u0035\u006b\u0064\u0051\u002c\u0058\u0020\u007a\u007c\u0028\u0043\u0022\u005f\u0033\u005d\u004a\u0069\u002c\u002f\u0027\u0066\u0054\u0062\u0031\u007a\u0031\u002e\u0031\u007e\u002a\u0022\u0067\u0056\u0078\u0021\u005e\u0069\u0036\u005e\u0078\u0068\u0063\u0027\u0073\u0029\u0037\u007e\u004e\u007c\u0032\u0058\u0042\u003e\u0054\u0026\u0058\u007a\u0069\u0069\u0035\u004e\u0046\u007a\u005b\u0025\u0034\u0045\u0031\u0056\u0046\u003b\u0048\u006c\u004c\u0034\u002a\u006e\u0064\u0043\u0023\u0079\u0056\u0066\u0025\u0069\u0039\u0034\u007c\u0059\u0028\u0045\u0061\u002d\u0041\u0057\u0071\u0062\u0076\u004c\u005b\u0021\u0027\u0030\u0023\u002a\u0061\u004c\u005d\u007c\u0075\u004c\u005f\u0038\u0067\u0051\u004c\u005e\u002a\u0061\u0047\u0021\u007a\u0033\u0020\u0031\u006c\u0062\u003d\u0027\u0040\u002b\u0054\u003d\u0029\u0051\u0076\u0044\u0031\u005e\u005a\u0067\u0062\u0036\u0069\u002f\u0045\u0039\u004a\u0065\u007a\u007a\u0026\u002d\u0064\u0079\u0027\u0060\u0025\u006f\u0072\u0054\u005a\u0039\u0032\u005a\u0029\u006e\u0034\u0034\u0029\u0045\u0035\u0073\u0022\u0057\u0063\u0071\u0032\u007e\u006e\u0047\u0025\u005e\u0028\u0034\u003d\u003e\u0053\u0039\u0028\u0027\u0053\u0056\u0079\u002b\u0053\u0055\u0063\u0027\u005a\u0052\u003e\u0038\u0056\u004b\u0058\u003c\u0024\u0052\u0033\u0049\u006b\u003d\u0046\u0035\u004e\u0034\u0048\u0050\u0065\u003d\u002e\u004f\u0054\u0056\u007d\u0032\u0023\u0071\u0074\u0033\u0079\u002b\u002b\u007b\u0070\u004a\u0056\u006a\u0034\u0041\u0066\u007d\u005a\u0024\u0065\u004d\u0033\u0029\u0024\u004e\u0048\u0060\u0030\u0046\u0039\u004d\u0078\u007b\u007b\u007c\u006f\u0022\u0036\u0051\u004e\u0074\u003e\u0048\u0060\u003f\u006f\u0029\u0053\u0044\u0028\u0078\u007a\u0033\u0063\u0031\u0054\u003f\u0076\u004b\u0074\u0040\u0026\u0027\u005c\u0025\u0024\u006b\u007a\u0076\u0057\u0052\u002e\u0041\u0038\u0049\u0079\u003f\u0044\u005c\u004b\u003f\u003a\u0036\u0076\u006d\u007a\u006b\u005b\u0074\u003d\u0068\u006b\u003f\u0071\u007d\u003e\u0051\u002f\u0074\u0039\u0046\u006f\u0034\u003a\u006b\u0065\u0054\u004c\u0061\u0073\u0058\u002e\u0033\u002c\u0068\u0035\u0053\u003f\u0036\u0065\u0044\u004d\u0045\u007c\u0031\u0058\u0056\u003a\u0052\u0053\u0040\u005d\u0038\u006c\u006d\u002a\u006d\u005b\u007e\u0033\u003b\u002d\u0042\u0024\u004d\u007e\u004b\u0041\u005b\u0059\u004c\u0021\u003e\u0078\u0033\u0075\u0065\u0034\u005e\u003e\u0035\u0072\u006d\u0078\u0029\u0056\u0079\u0069\u0021\u006c\u0059\u007c\u004a\u002f\u003c\u0036\u003d\u005e\u0024\u007b\u0053\u0050\u0044\u003e\u005c\u0044\u0069\u0054\u002b\u003b\u0027\u0057\u0048\u0052\u003c\u0046\u004e\u0049\u0056\u007b\u0051\u0045\u005a\u003a\u0024\u007e\u0039\u0067\u0068\u006d\u0050\u007d\u0022\u005e\u0041\u0046\u0072\u0075\u0041\u006a\u002e\u004b\u0039\u0060\u0050\u0020\u0069\u0043\u0063\u0068\u005d\u0060\u005b\u0070\u005a\u0079\u0059\u0020\u002d\u0030\u005e\u006a\u0067\u002b\u004a\u0064\u0044\u0063\u0036\u0050\u007e\u0070\u0045\u006b\u0051\u0030\u003e\u006b\u0047\u0075\u002e\u004f\u004e\u0072\u002e\u004a\u0037\u0057\u0021\u007d\u0074\u0050\u0066\u006e\u0046\u0061\u0054\u006a\u0050\u0057\u006f\u002e\u0031\u004c\u004d\u003f\u0032\u004e\u007b\u0058\u0049\u002e\u006e\u003a\u0042\u0049\u0073\u006f\u0029\u006a\u0074\u0069\u002d\u002b\u006d\u0057\u0068\u0057\u0067\u0079\u004d\u0047\u003b\u003f\u0033\u0076\u0027\u007d\u0054\u0078\u005c\u004b\u007b\u0049\u005a\u004b\u0024\u004e\u0028\u0057\u0022\u004c\u005b\u006e\u0037\u0030\u0043\u002b\u0041\u0079\u0035\u0060\u0053\u0022\u006b\u0057\u0074\u0053\u0036\u0037\u004e\u0044\u0022\u005d\u005e\u007b\u0039\u0034\u0021\u005f\u005c\u004d\u003c\u002b\u0022\u0021\u0075\u004b\u0023\u0020\u0026\u0075\u0029\u0060\u0073\u0030\u0047\u002a\u0020\u0047\u0026\u006c\u0058\u005e\u0079\u0055\u003e\u004d\u0046\u005c\u0079\u0066\u0033\u004d\u0059\u003d\u0029\u0069\u003c\u004d\u0056\u0062\u006e\u0025\u0045\u003a\u0034\u0057\u003a\u002f\u0060\u0077\u003f\u0070\u0059\u006b\u0078\u002d\u0024\u0051\u0071\u006c\u0022\u006e\u0027\u0058\u0046\u003f\u0049\u0022\u0056\u006c\u0032\u0034\u003f\u006b\u003d\u0033\u003a\u003d\u0032\u0038\u004a\u0025\u0034\u0067\u006b\u0060\u0043\u003f\u003d\u002c\u002b\u002e\u0022\u006d\u0049\u0020\u0036\u0035\u004a\u004e\u005b\u003e\u0031\u0060\u004a\u005b\u003e\u002a\u006e\u0068\u0046\u0063\u003b\u0033\u0052\u0049\u0069\u0068\u005f\u0041\u0031\u0041\u0077\u0068\u0040\u007b\u0050\u004a\u0065\u0056\u0050\u0064\u003d\u007b\u0044\u002d\u0068\u002e\u0037\u0071\u0056\u004a\u006b\u0078\u004d\u004f\u007c\u005c\u002e\u0033\u002c\u0021\u0054\u0047\u0072\u0037\u0058\u0079\u004b\u0068\u0034\u0027\u003b\u0021\u0035\u002b\u0035\u0050\u0031\u0021\u0064\u0032\u002f\u0029\u0072\u002b\u0078\u0050\u0068\u0045\u003c\u0034\u0030\u0071\u0052\u0076\u0044\u0036\u006a\u0036\u002b\u0034\u002b\u004d\u0033\u003e\u0056\u0064\u0039\u006f\u0069\u0073\u0047\u0023\u006c\u0054\u003d\u0075\u0069\u007d\u0061\u007e\u003e\u0064\u0045\u0036\u0045\u002c\u0063\u003a\u007b\u0032\u0053\u004a\u007e\u004d\u0070\u0035\u0029\u002b\u0037\u0054\u003d\u006d\u0029\u0024\u0029\u0030\u007b\u006e\u0042\u006f\u005b\u002c\u0074\u004d\u0054\u0077\u002a\u0021\u0045\u0076\u0024\u006c\u0056\u006a\u0033\u0062\u0068\u004d\u0020\u0055\u0061\u0058\u0055